"""NEXORA marketing strategy (English) -> NEXORA_Marketing_Strategy.pdf. python3 build.py"""
import os
from playwright.sync_api import sync_playwright
HERE = os.path.dirname(os.path.abspath(__file__))
NAVY, TEAL, MUTED, LINE = "#101C2C", "#19C6B4", "#536273", "#DDE2E8"
CSS = f"""@font-face{{font-family:D;src:url(DMSans.ttf);font-weight:100 1000}}
@page{{size:A4;margin:0}}*{{box-sizing:border-box;margin:0}}body{{font-family:D,sans-serif;color:{NAVY};font-size:10.8px;line-height:1.55;-webkit-print-color-adjust:exact;print-color-adjust:exact}}
.pg{{width:794px;height:1123px;overflow:hidden;padding:42px 54px 36px;position:relative;page-break-after:always;background:#F5F7FA}}.pg:last-child{{page-break-after:auto}}
.dk{{background:{NAVY};color:#fff}}
.top{{display:flex;justify-content:space-between;align-items:center;font-size:9.5px;letter-spacing:2.5px;color:{MUTED};padding-bottom:12px;border-bottom:1px solid {LINE};margin-bottom:18px}}.top b{{display:flex;align-items:center;gap:8px;color:{NAVY};letter-spacing:3px}}.top img{{height:18px}}
.k{{color:{TEAL};font-weight:700;letter-spacing:3px;font-size:10px;text-transform:uppercase;margin-bottom:6px}}h1{{font-size:25px;line-height:1.25;font-weight:700;margin-bottom:8px}}h2{{font-size:14px;margin:12px 0 4px;font-weight:700}}h3{{font-size:12px;margin:12px 0 3px;color:{TEAL};text-transform:uppercase;letter-spacing:1.5px}}
p{{color:{MUTED};margin-bottom:7px}}ul{{list-style:none;margin:4px 0 8px}}li{{position:relative;padding-left:15px;margin-bottom:3px;color:{NAVY}}}li:before{{content:"";position:absolute;left:0;top:7px;width:5px;height:5px;background:{TEAL};border-radius:50%}}
table{{width:100%;border-collapse:collapse;margin:8px 0 10px;font-size:9.9px}}th{{background:{NAVY};color:#fff;text-align:left;padding:5px 8px;font-weight:600}}td{{padding:5px 8px;border:1px solid {LINE};vertical-align:top;background:#fff}}tr:nth-child(even) td{{background:#FAFBFC}}
.box{{background:{NAVY};color:#fff;padding:16px 20px;margin:8px 0}}.box p,.box li{{color:#DDE6F0}}.box li:before{{background:{TEAL}}}.call{{background:#E4F7F4;border-left:4px solid {TEAL};padding:10px 14px;margin:10px 0;color:{NAVY}}}.call p{{margin:0;color:{NAVY}}}
.cols{{display:grid;grid-template-columns:1fr 1fr;gap:22px}}.tag{{display:inline-block;background:#E4F7F4;color:#0E7F73;font-weight:700;font-size:9.5px;padding:2px 8px;border-radius:10px;margin-right:6px}}
.cover{{height:1123px;background:{NAVY};color:#fff;padding:90px 70px;position:relative;page-break-after:always}}.cover h1{{font-size:44px;margin-top:290px;line-height:1.15}}.cover .s{{color:{TEAL};font-weight:700;letter-spacing:4px;font-size:12px}}
"""
def pg(n, body, k="", title="", dark=False):
    head = f'<div class="top"><b><img src="mark.png">NEXORA</b><span>MARKETING STRATEGY</span></div>' + (f'<div class="k">{k}</div><h1>{title}</h1>' if title else "")
    return f'<section class="pg{" dk" if dark else ""}">{head}{body}</section>'
def ul(*a): return "<ul>" + "".join(f"<li>{x}</li>" for x in a) + "</ul>"
def tb(head, rows): return "<table><tr>" + "".join(f"<th>{h}</th>" for h in head) + "</tr>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</table>"
P = []
P.append(f'<section class="cover"><img src="mark.png" style="height:70px"><div class="s" style="margin-top:20px">NEXORA · BUSINESS DEVELOPMENT &amp; PERFORMANCE</div><h1>Marketing strategy<br>for the Egyptian SME market</h1><p style="color:#B9C6D6;font-size:15px;margin-top:20px;max-width:520px">How NEXORA wins its first clients, builds proof, and grows into a recognised growth partner. Built from the company profile and a first read of the Egyptian market.</p><p style="position:absolute;bottom:70px;color:#8FA1B5;font-size:11px">Working draft · figures marked "hypothesis" must be validated with NEXORA&#39;s own data · Egypt</p></section>')
P.append(pg(2, '''<div class="call"><p><b>The one-line strategy:</b> become the go-to growth partner for owner-led service businesses in Egypt, starting in fitness and wellness and food and hospitality, with one paid entry product, 3 published pilot results, and referral partnerships doing most of the selling.</p></div>
<h2>Why this strategy</h2>''' + ul("<b>The profile sells everything.</b> Four pillars and about 45 services read as generic. Buyers pay to fix a specific problem, so we lead with a narrow wedge and widen after proof.", "<b>There is no proof yet.</b> The profile honestly says no verified case studies exist. Getting 2 to 3 measured pilots is the single most valuable marketing asset.", "<b>The buyers are cautious and cash-sensitive.</b> Inflation re-accelerated to about 15% in March 2026 and the pound weakened (about 50.6 per dollar in July). Owners prefer short projects with visible returns over long retainers.", "<b>Trust travels through people.</b> In SME markets, introductions from accountants, bankers, landlords and peers beat cold ads.") +
'''<h2>The plan on a page</h2>''' + tb(["", "Decision"], [["Who", "Owner-led businesses, 10 to 100 staff, in fitness and wellness, food and hospitality, and professional services"], ["What we sell first", "Business Performance Assessment: fixed fee, 2 to 3 weeks, ends in a written plan"], ["Why us", "Strategy connected to execution: named owners, KPIs, documented systems, capability left behind"], ["How we reach them", "Referral partners, founder-led LinkedIn, Arabic Facebook and Instagram content, free workshops, targeted outreach"], ["Proof", "3 pilots with permission to publish measured results"], ["First 90 days", "Foundation (weeks 1-2), pilots and launch (3-8), scale and case studies (9-12)"], ["Success looks like", "Qualified conversations per week, assessments sold, assessment-to-project conversion, published case studies"]]) +
'''<h2>What we know vs. what we are assuming</h2><p><b>Known (from the profile):</b> services, engagement models, methodology, KPI menu, target sectors, honest-claims policy. <b>Not yet known:</b> who delivers the work, team size, capacity, pricing, cash runway, existing network. The plan assumes a small founding team and no existing client base; change anything that is wrong.</p>''', "Executive summary", "Win a narrow market, then widen"))
P.append(pg(3, '''<h2>Market context (read with caution)</h2>''' + ul("<b>SMEs dominate the economy.</b> Estimates range from about 43% to 80% of GDP depending on definition; only roughly 20 to 33% of SMEs have access to bank credit, with a financing gap of about $39-46 billion (DFC 2025; Business Monthly 2024). Implication: many owners run lean, informal businesses with little management infrastructure, which is exactly the gap NEXORA fills, but budgets are tight.", "<b>Consulting is a modeled ~$1.7 billion market</b> growing near 4% a year (Mordor Intelligence, a single unaudited source). Demand is shifting to quick cost-saving work and digital projects.", "<b>Macro is volatile.</b> Growth is forecast near 4.5 to 5%; inflation is rising again and the pound has weakened since the Gulf conflict began (Reuters poll, BMI, July 2026).") + '''<h2>Who we compete with</h2>''' + tb(["Competitor type", "Strength", "Weakness we can exploit"], [["Big 4 and large firms", "Brand, credibility, corporate clients", "Price, slow, built for large enterprises"], ["Boutique consultancies", "Specialists, relationships", "Often narrow; hard to see outcomes"], ["Marketing and digital agencies", "Cheap, fast content and ads", "Rarely connect to sales, operations or KPIs"], ["Freelancers and independent trainers", "Low price, personal", "No system, no accountability, key-person risk"], ["In-house hires", "Always present", "Cost, one person's view, no outside benchmark"]]) +
'''<div class="call"><p><b>Gap to claim:</b> nobody owns "the integrated, measurable, owner-friendly growth partner for Egyptian SMEs". NEXORA's real advantage is joining marketing, sales process, operations and training, then measuring them together. A competitor scan (names, prices, claims) should be the first research task.</p></div>
<h2>Customer we serve first (ICP)</h2>''' + tb(["Segment", "Why start here", "Typical trigger", "Entry offer"], [["Fitness and wellness (gyms, studios, clinics)", "Fragmented; clear metrics (trials, conversion, retention); front-desk sales and shift consistency are fixable", "Memberships flat or falling in one branch; owner is the only closer", "Assessment + front-desk sales process + SOPs"], ["Food and hospitality (cafés, restaurants, chains)", "Repeat-visit businesses; consistency across shifts matters; strong social channels", "Quality varies by shift; opening of second branch; weak local marketing", "Assessment + service standards + local marketing plan"], ["Professional services (clinics, firms, agencies)", "Owner-dependent; long sales cycles", "Founder is the bottleneck for every sale and decision", "Assessment + pipeline and proposal process"]]) + '<p>Secondary (later): startups needing go-to-market; B2B service companies; retail. Screen out: businesses with no owner access, no willingness to share data, or expecting guaranteed results.</p>', "Situation", "Market, competitors and customer"))
P.append(pg(4, '''<h2>Buyer personas</h2>''' + tb(["Persona", "Jobs and pains", "What convinces them"], [["The Owner-Founder (main buyer)", "Growth is stuck; everything depends on them; no reliable numbers; fears wasting money on consultants", "Clear scope and fee, a first deliverable in weeks, references from similar businesses, no jargon"], ["The General Manager / Operations lead", "Quality varies, constant firefighting, unclear roles", "SOP and KPI examples, a plan they can run, training for the team"], ["The Marketing or Sales lead", "Leads are unqualified, follow-up is inconsistent, ads are hard to justify", "A funnel with owners, simple dashboards, proof of lead-to-customer tracking"]]) + '''<h2>Positioning</h2><div class="box"><p style="color:#fff"><b>For</b> owner-led businesses in Egypt that have outgrown founder-driven selling and word-of-mouth, <b>NEXORA</b> is the business growth and performance partner that connects strategy, marketing, sales, operations and training into one measurable plan, <b>unlike</b> agencies that only run campaigns or consultants that hand over a report, because every recommendation comes with named owners, documented systems and agreed KPIs.</p></div>
<h2>Messaging pillars</h2>''' + tb(["Pillar", "Message", "Proof we can show (honestly)"], [["1. Alignment", "Most growing businesses do not lack effort; they lack alignment between marketing, sales, operations and people", "The integrated model and the six-stage method"], ["2. Plans that run", "We leave you with systems and owners, not a slide deck", "Deliverables list: SOPs, dashboards, process maps, scorecards"], ["3. Measured, not promised", "We agree KPIs up front and report against them; we do not guarantee results", "Responsibility framework and KPI menu"], ["4. Capability that stays", "Your team learns the system so improvement continues without us", "Training approach: needs assessment to evaluation"]]) +
'''<h3>Tone</h3><p>Plain, practical, confident. Arabic-first for owners (Egyptian business Arabic, not academic), English for LinkedIn and corporate audiences. No superlatives, no market-leader claims, no guaranteed results (keep the profile's honesty policy: it is a trust asset).</p>
<h3>Objections and answers</h3>''' + tb(["Objection", "Answer"], [["\"Consultants only give reports\"", "Every engagement lists deliverables and owners; implementation support is scoped and measured."], ["\"Too expensive right now\"", "Start with a fixed-fee assessment; cost is tied to the bottleneck being fixed; no long retainer needed."], ["\"We can do it ourselves\"", "Often true; we speed it up and bring an outside benchmark. Training leaves the skill inside the team."], ["\"You have no case studies\"", "Correct. We offer pilot terms in exchange for permission to publish measured results; here is our case-study framework."]]), "Positioning", "What we stand for"))
P.append(pg(5, '''<h2>Offer architecture</h2><p>Sell a ladder, not a menu of 45 services. Each step should be easy to say yes to.</p>''' + tb(["Step", "Offer", "Format", "Purpose"], [["0. Free", "Business Health Scorecard (10 questions, 5 minutes) + free 30-minute workshop", "Self-serve, WhatsApp or web", "Capture leads, start the conversation"], ["1. Entry (paid)", "Business Performance Assessment", "Fixed fee, 2 to 3 weeks, written findings and a 90-day plan", "Low-risk first purchase; shows how NEXORA thinks"], ["2. Sprint", "Productised 30-60 day projects, e.g. Sales Follow-up System, SOP Sprint, Marketing Plan and Content Calendar, Manager Training Pack", "Fixed scope and deliverables", "Fast visible result; builds case studies"], ["3. Partnership", "Ongoing Growth Partnership", "Monthly or quarterly cycle with KPI review", "Recurring revenue"], ["4. Capability", "Corporate Training programmes", "Needs assessment to evaluation", "Revenue and lasting change; strong add-on"]]) + '''<div class="call"><p><b>Pricing guidance:</b> price by scope and value, publish "from" ranges only after 3 to 5 proposals teach you what the market accepts; invoice part upfront, milestone the rest; add a written change-control clause. Review prices for EGP volatility every quarter.</p></div>
<h2>Funnel</h2>''' + tb(["Stage", "Goal", "Main channels", "Metric"], [["Aware", "Owners know NEXORA exists for their problem", "LinkedIn, Facebook and Instagram, referral partners, events", "Reach, profile visits, referral introductions"], ["Engage", "They take a small step", "Scorecard, workshop, newsletter, WhatsApp", "Scorecard completions, workshop attendees"], ["Qualify", "Conversation with a fit buyer", "Discovery call (30 min)", "Qualified calls per week"], ["Convert", "Paid assessment or sprint", "Proposal within 48 hours, follow-up cadence", "Proposals sent, close rate"], ["Expand", "Project or partnership; referral", "Review meeting at end of assessment", "Assessment-to-project rate, referrals"]]) + '''<h3>Sales process rules</h3>''' + ul("Respond to every enquiry within 2 working hours (WhatsApp first).", "One discovery script: goal, bottleneck, numbers they have, who decides, timeline, budget range.", "Proposal in 48 hours; follow up on day 2, 5, 10 and 20; log everything in a simple CRM (Airtable, Notion or HubSpot free).", "Every lost deal gets a short reason code to feed positioning."), "Offer and funnel", "A ladder buyers can climb"))
P.append(pg(6, '''<h2>Channels (ranked by expected return)</h2>''' + tb(["#", "Channel", "How to use it", "Effort / cost"], [["1", "Referral partners", "Accountants and tax advisers, SME desks at banks, incubators and coworking spaces, landlords, franchise and equipment suppliers, POS and software vendors, associations. Offer a clear referral note and a joint workshop.", "Time; no ad cost"], ["2", "Founder-led LinkedIn", "2 to 3 posts a week from the founder(s), plus the company page. Diagnose-style posts, mini case notes, templates. Comment daily on owner and operator posts.", "Low"], ["3", "Facebook and Instagram (Arabic)", "Owner-facing education in Arabic: short reels, carousels and stories. This is where many Egyptian SME owners spend time.", "Medium (content production)"], ["4", "Workshops and webinars", "Free monthly workshop per sector: \"Why your sales follow-up leaks\", \"SOPs in a week\". Co-host with a partner. Convert with the Scorecard and an assessment offer.", "Medium"], ["5", "Targeted outbound", "A list of 200 ideal accounts; personal LinkedIn or WhatsApp messages referencing a specific observation. No mass blasts.", "Medium, fully measurable"], ["6", "Website and search", "Arabic and English site, one page per sector offer, Scorecard landing page, Google Business Profile. SEO is a slow compounding asset.", "Medium upfront"], ["7", "Paid ads (test only)", "Small Meta lead-form and LinkedIn tests to promote the Scorecard or workshop, after organic messages are proven.", "Controlled test budget"]]) +
'''<h2>Content strategy</h2>''' + tb(["Pillar", "Examples", "Formats"], [["Diagnose", "\"5 signs your sales follow-up is leaking\", \"The owner bottleneck test\"", "Carousel, short video, checklist"], ["Systems", "\"SOP in one page\", \"A weekly KPI review in 20 minutes\", before/after templates", "Templates, PDFs, reels"], ["Numbers", "\"Which 5 numbers every café owner should check weekly\", KPI explainers", "Infographic, mini dashboard"], ["People", "\"Why training fails and how to make it stick\", manager-in-the-first-90-days", "Article, workshop clip"], ["Proof", "Pilot results, client quote (with permission), before/after metrics", "Case study, testimonial, LinkedIn post"]]) + '''<p><b>Cadence (starting point):</b> 3 LinkedIn posts, 3 to 4 Facebook/Instagram posts, 1 newsletter and 1 workshop per month; one lead magnet released every month. Always end with a clear next step (Scorecard, WhatsApp, workshop).</p>''', "Channels and content", "Where and how we show up"))
P.append(pg(7, '''<h2>90-day roadmap</h2>''' + tb(["Weeks", "Focus", "Deliverables", "Owner"], [["1-2", "Foundation", "Sector positioning pages; Arabic and English profile (Arabic done); real contact details; LinkedIn and Facebook pages; Business Health Scorecard (10 questions); CRM; proposal and assessment templates; pricing v1", "Founder + marketing lead"], ["3-4", "Pilots and partners", "Recruit 3 pilot clients (discount for permission to publish measured results); list 30 partners and meet 10; publish first 8 posts; run first free workshop", "Founder"], ["5-8", "Launch", "Deliver pilots with agreed KPIs; weekly content cadence; 200-account outbound list started; 2 co-hosted workshops; first referral introductions", "Team"], ["9-10", "Prove", "Collect baseline vs. result for each pilot; write 3 case studies (client approval); client quote and photo or logo with permission", "Founder + delivery lead"], ["11-12", "Scale", "Publish case studies; sector landing pages updated with proof; paid test (Scorecard promotion); decide which sector and offer to double down on", "Founder"]]) + '''<h2>KPIs and review rhythm</h2><p>Targets below are starting hypotheses. Set real numbers after 4 weeks of baseline data.</p>''' + tb(["Level", "Metric", "Starting hypothesis (to calibrate)"], [["Activity", "Posts published, partner meetings, outbound messages sent", "As per cadence above; 10 partner meetings in 90 days"], ["Leads", "Scorecard completions, workshop sign-ups, WhatsApp enquiries", "Track weekly; aim to double month on month from a small base"], ["Qualified", "Discovery calls held", "3 to 5 per week by week 8"], ["Revenue", "Assessments sold, assessment-to-project conversion, average deal, sales cycle", "Convert 30-50% of assessments into a next project (hypothesis)"], ["Proof", "Published case studies, testimonials, referrals received", "3 case studies, first referral deal by day 90"], ["Efficiency", "Cost per qualified lead, cost per assessment", "Calculate once paid tests start"]]) + '''<p>Review weekly (15 minutes: leads, calls, proposals) and monthly (30 minutes: channel mix, content performance, what to stop).</p>
<h2>Budget guidance (percentages, not amounts)</h2>''' + tb(["Area", "Share of marketing budget (assumption)"], [["Content, design and website", "35%"], ["Partnerships, workshops and events", "25%"], ["Tools (CRM, email, scheduling, analytics)", "10%"], ["Paid tests (Meta, LinkedIn)", "15%"], ["Outbound support and reserve", "15%"]]), "Execution", "90-day plan and measurement"))
P.append(pg(8, '''<h2>Risks and mitigations</h2>''' + tb(["Risk", "Why it matters", "Mitigation"], [["Too broad a message", "Buyers cannot tell what NEXORA is for", "One wedge per sector, one entry offer, widen only after proof"], ["No proof", "Weak trust in a market that has seen empty decks", "Pilot terms for publishable results; case-study framework; honest claims"], ["Slow cash collection", "SME payment delays", "Deposit upfront, milestone invoices, clear change control"], ["Delivery capacity", "Selling faster than the team can deliver", "Cap pilots at 3; productised sprints; partner for training"], ["Currency and inflation", "Clients freeze spending", "Cost-saving framing; short projects; quarterly price review"], ["Key-person dependence", "Brand is the founder", "Document methods; build a second voice; train juniors"], ["Compliance gaps", "Credibility and fines", "Confirm company, tax and e-invoicing set-up with an accountant; add NDAs and data-handling terms to contracts"]]) + '''<h2>Assets to build first</h2>''' + ul("Arabic and English website with sector pages and the Scorecard (Arabic profile PDF is ready).", "Business Health Scorecard (10 questions, scored; result report by WhatsApp or email).", "Assessment proposal template and a one-page entry-offer sheet.", "Case-study template (the profile's 9-point framework) and a pilot agreement with a publication clause.", "Partner kit: one-page introduction, referral note, workshop outline.", "Content system: monthly calendar, post templates, a brand style sheet.") + '''<h2>Open questions I need answered</h2>''' + ul("Who delivers the work (team, capacity, partners)?", "Which sector do you know best, and do you already have contacts there?", "Are there any existing clients or testimonials, even informal?", "What budget and time can you commit per month?", "Target price level for the assessment, and the number of clients you can serve at once?", "Is the focus Egypt only, or the Gulf as well in year one?") + '''<div class="call"><p><b>Next steps I can do now:</b> competitor scan, Business Health Scorecard, sector landing-page copy (Arabic and English), 90-day content calendar with ready-made posts, a partner outreach kit, and the pilot agreement and proposal templates.</p></div><p style="font-size:10px;color:#7F8C9B;margin-top:14px">Sources for market context: DFC (2025) and Business Monthly (2024) on SME share and financing gap; Mordor Intelligence on consulting market size (modeled, single source); Reuters poll and BMI via Zawya and Enterprise (2026) on growth, inflation and the pound. Figures differ by source and should be re-checked before external use.</p>''', "Risks and next steps", "What could go wrong, and what to build"))
open(f"{HERE}/strategy.html", "w", encoding="utf-8").write(f'<!doctype html><meta charset="utf-8"><style>{CSS}</style>' + "".join(P))
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/opt/pw-browsers/chromium-1194/chrome-linux/chrome", args=["--no-sandbox", "--allow-file-access-from-files"])
    pg_ = b.new_page(); pg_.goto(f"file://{HERE}/strategy.html"); pg_.wait_for_timeout(600)
    pg_.pdf(path=f"{HERE}/NEXORA_Marketing_Strategy.pdf", format="A4", print_background=True, margin=dict(top="0", bottom="0", left="0", right="0")); b.close()
print("ok")
